  r=new Record{Name="당직 예시",OriginalWorker="김담당",Reason="연차 대체",Institution="예시학교",Start=new DateTime(2026,9,7),End=new DateTime(2026,9,13)};Engine.Fill(r);LoadUI();RefreshAll();job.SelectedIndex=jobs.FindIndex(x=>x.name.Contains("당직")&&x.name.Contains("2인"));AssertUI(hours.Value==8.5m&&hours.Maximum==24&&weekendField.Visible==false,"guard fields configured while contract page hidden");
  tabs.SelectedIndex=0;Show();AssertUI(weekendField.Visible&&guardFields.Visible,"guard contract fields visible");AssertUI(unmannedSaturday.Checked&&!unmannedSunday.Checked&&r.Days.Count==4,"guard switch creates alternating schedule");unmannedSunday.Checked=true;AssertUI(!unmannedSaturday.Checked&&unmannedSunday.Checked&&!r.Days.ContainsKey("2026-09-13"),"Sunday security excludes duty without shifting cycle");unmannedSunday.Checked=false;AssertUI(unmannedSunday.Checked&&!unmannedSaturday.Checked,"security day cannot be empty");unmannedSaturday.Checked=true;AssertUI(r.Days.Count==4,"Saturday security restores schedule");Set("nightDays",2);Set("publicDays",1);CaptureScreen(Path.Combine(folder,"guard-contract.png"));
  tabs.SelectedIndex=2;employmentExcluded.Checked=true;employmentReason.Text="적용 제외 사유 확인";AssertUI(result.Employment==0&&employmentReason.Enabled,"employment exclusion controls recalculate");loading=true;employmentReason.Text="";loading=false;CaptureScreen(Path.Combine(folder,"guard-money.png"));loading=true;employmentReason.Text=r.EmploymentExclusionReason;loading=false;tabs.SelectedIndex=3;CaptureScreen(Path.Combine(folder,"guard-output.png"));
  foreach(string kind in new[]{"임금산정표","급여명세서"}){string file=CreateDocument(kind,true);AssertUI(File.Exists(file)&&file.EndsWith(".pdf"),"PDF routes to configured document folder");}
  employmentExcluded.Checked=false;foreach(string key in new[]{"food","health","care","pension","tax","local","extra"})Set(key,1000);Set("within",1);Set("overtime",1);tabs.SelectedIndex=3;CaptureScreen(Path.Combine(folder,"all-items-output.png"));
  tabs.SelectedIndex=0;end.Value=start.Value;AssertUI(!numbers["meal"].Enabled&&numbers["meal"].Text==""&&!numbers["allowance"].Enabled,"under fifteen shows blank excluded allowance inputs");end.Value=start.Value.AddDays(6);AssertUI(numbers["meal"].Enabled&&numbers["meal"].Value==100000,"eligible allowance restored after period change");
  job.SelectedIndex=jobs.FindIndex(x=>x.name=="조리실무사");AssertUI(!weekendField.Visible&&!guardFields.Visible&&hours.Maximum==8&&r.NightDays==0,"ordinary job restores ordinary controls");dirty=false;
 }
}
}
